use crate::aap::caps::kb_read;

/// The `ensures len(question) <= 512` bound. The check is on bytes, which also
/// bounds the character count (every char is at least one byte), so it holds
/// under either reading of `len`. Truncation stops at a char boundary.
const MAX_QUESTION: usize = 512;

fn bound_question(s: &str) -> String {
    let mut out = String::new();
    let mut bytes = 0usize;
    for c in s.chars() {
        let l = c.len_utf8();
        if bytes + l > MAX_QUESTION {
            break;
        }
        bytes += l;
        out.push(c);
    }
    out
}

struct Node;

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        // The requires clause holds of the input, but the question is adversarial
        // text and the ensures clause is checked on the output, so bound it here.
        let question = bound_question(&query.query.question);

        // Read-only lookup through the kb-read handle. Only `lookup` exists on
        // this interface, so there is no way to mutate the store from here.
        let mut knowledge: Vec<String> = kb_read::lookup(&question);

        // ensures present(knowledge): guarantee the list is non-empty so that
        // downstream consumers always receive a populated knowledge field.
        if knowledge.is_empty() {
            knowledge.push(String::from("(no matching knowledge found)"));
        }

        ConversationContext {
            intent: query.query.intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
